// Where the browser viewer keeps its private key and the circle keys it holds.
//
// Three custody modes, strongest first. NONE of them ever sends a secret to the
// server, and nothing secret is written to localStorage or sessionStorage:
//
//  device      Ed25519 and X25519 private keys are generated by WebCrypto as
//              NON-EXTRACTABLE CryptoKeys and stored (as CryptoKey objects) in
//              IndexedDB. Script, including an XSS payload, can ask them to sign
//              or agree a key while the page runs but can never read the bytes.
//              The circle keys are encrypted with a non-extractable AES-GCM
//              CryptoKey held the same way. Needs a browser with WebCrypto
//              Ed25519 and X25519 (Chrome 137+, Firefox 129+, Safari 17+).
//              Limit: anyone who copies the browser profile from disk may be
//              able to copy the opaque key store; use the passphrase mode on a
//              shared computer.
//  passphrase  A 32-byte identity seed (same derivation as the phones) and the
//              circle keys are sealed (XChaCha20-Poly1305) under a key from
//              Argon2id (64 MiB, 3 passes) of a passphrase and stored in
//              IndexedDB. Unlock once per session; the unlocked keys live only
//              in memory (extractable by script while unlocked).
//  session     Nothing is stored. Keys live in memory and vanish when the tab
//              closes (a disposable viewer: revoke it afterwards).

import { argon2idAsync } from '@noble/hashes/argon2.js'
import { xchacha20poly1305 } from '@noble/ciphers/chacha.js'
import { ed25519, x25519 } from '@noble/curves/ed25519.js'
import {
  E2eeError,
  cat,
  deriveIdentity,
  edPublic,
  hkdfSha256,
  randomBytes,
  unb64,
  b64,
  utf8,
  xPublic,
} from './core.ts'

export type CustodyMode = 'device' | 'passphrase' | 'session' | 'account'

/** What the rest of the code needs from a key holder; secrets stay inside. */
export interface KeyOps {
  mode: CustodyMode
  edPub: Uint8Array
  xPub: Uint8Array
  sign(msg: Uint8Array): Promise<Uint8Array>
  /** X25519(own secret, peer public); rejects an all-zero result. */
  ecdh(peer: Uint8Array): Promise<Uint8Array>
}

/** Minimal async key-value store (IndexedDB in the browser, a Map in tests). */
export interface KV {
  get(key: string): Promise<unknown>
  put(key: string, value: unknown): Promise<void>
  del(key: string): Promise<void>
  keys(prefix: string): Promise<string[]>
}

export class MemoryKV implements KV {
  m = new Map<string, unknown>()
  async get(k: string) {
    return this.m.get(k)
  }
  async put(k: string, v: unknown) {
    this.m.set(k, v)
  }
  async del(k: string) {
    this.m.delete(k)
  }
  async keys(prefix: string) {
    return [...this.m.keys()].filter((k) => k.startsWith(prefix))
  }
}

const DB_NAME = 'openfamily-e2ee-viewer'
const STORE = 'kv'

export class IdbKV implements KV {
  private db: Promise<IDBDatabase> | null = null
  private open(): Promise<IDBDatabase> {
    this.db ??= new Promise((resolve, reject) => {
      const r = indexedDB.open(DB_NAME, 1)
      r.onupgradeneeded = () => r.result.createObjectStore(STORE)
      r.onsuccess = () => resolve(r.result)
      r.onerror = () => reject(r.error)
    })
    return this.db
  }
  private async tx<T>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
    const db = await this.open()
    return new Promise((resolve, reject) => {
      const req = f(db.transaction(STORE, mode).objectStore(STORE))
      req.onsuccess = () => resolve(req.result)
      req.onerror = () => reject(req.error)
    })
  }
  get(k: string) {
    return this.tx('readonly', (s) => s.get(k))
  }
  async put(k: string, v: unknown) {
    await this.tx('readwrite', (s) => s.put(v, k))
  }
  async del(k: string) {
    await this.tx('readwrite', (s) => s.delete(k))
  }
  async keys(prefix: string) {
    const all = (await this.tx('readonly', (s) => s.getAllKeys())) as IDBValidKey[]
    return all.map(String).filter((k) => k.startsWith(prefix))
  }
}

// ------------------------------------------------------------- ops impls

class MemoryOps implements KeyOps {
  edPub: Uint8Array
  xPub: Uint8Array
  constructor(
    public mode: CustodyMode,
    private edSeed: Uint8Array,
    private xSecret: Uint8Array,
  ) {
    this.edPub = edPublic(edSeed)
    this.xPub = xPublic(xSecret)
  }
  async sign(msg: Uint8Array) {
    return ed25519.sign(msg, this.edSeed)
  }
  async ecdh(peer: Uint8Array) {
    return x25519.getSharedSecret(this.xSecret, peer)
  }
}

class WebCryptoOps implements KeyOps {
  mode: CustodyMode = 'device'
  constructor(
    private edPriv: CryptoKey,
    private xPriv: CryptoKey,
    public edPub: Uint8Array,
    public xPub: Uint8Array,
  ) {}
  async sign(msg: Uint8Array) {
    return new Uint8Array(await crypto.subtle.sign({ name: 'Ed25519' }, this.edPriv, msg as BufferSource))
  }
  async ecdh(peer: Uint8Array) {
    const pk = await crypto.subtle.importKey('raw', peer as BufferSource, { name: 'X25519' }, true, [])
    return new Uint8Array(await crypto.subtle.deriveBits({ name: 'X25519', public: pk }, this.xPriv, 256))
  }
}

export function webCryptoSupported(): boolean {
  return typeof crypto !== 'undefined' && !!crypto.subtle && typeof indexedDB !== 'undefined'
}

// ------------------------------------------------------------- vault

/** Holds circle keys (per epoch), the pinned log head and the sync cursors. */
export interface Vault {
  mode: CustodyMode
  putCircleKey(circleId: string, epoch: number, key: Uint8Array): Promise<void>
  getCircleKey(circleId: string, epoch: number): Promise<Uint8Array | null>
  heldEpochs(circleId: string): Promise<number[]>
}

const ckName = (userId: string, circleId: string, epoch: number) => `ck:${userId}:${circleId}:${epoch}`

class AesVault implements Vault {
  mode: CustodyMode = 'device'
  constructor(
    private kv: KV,
    private userId: string,
    private aes: CryptoKey,
  ) {}
  async putCircleKey(circleId: string, epoch: number, key: Uint8Array) {
    const iv = randomBytes(12)
    const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: iv as BufferSource }, this.aes, key as BufferSource))
    await this.kv.put(ckName(this.userId, circleId, epoch), cat(iv, ct))
  }
  async getCircleKey(circleId: string, epoch: number) {
    const v = (await this.kv.get(ckName(this.userId, circleId, epoch))) as Uint8Array | undefined
    if (!v) return null
    try {
      return new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: v.slice(0, 12) as BufferSource }, this.aes, v.slice(12) as BufferSource))
    } catch {
      return null
    }
  }
  async heldEpochs(circleId: string) {
    return epochsFrom(await this.kv.keys(`ck:${this.userId}:${circleId}:`))
  }
}

class XChaChaVault implements Vault {
  constructor(
    public mode: CustodyMode,
    private kv: KV | null,
    private userId: string,
    private key: Uint8Array,
    private mem = new Map<string, Uint8Array>(),
  ) {}
  async putCircleKey(circleId: string, epoch: number, key: Uint8Array) {
    const name = ckName(this.userId, circleId, epoch)
    if (!this.kv) {
      this.mem.set(name, key.slice())
      return
    }
    const nonce = randomBytes(24)
    await this.kv.put(name, cat(nonce, xchacha20poly1305(this.key, nonce, utf8(name)).encrypt(key)))
  }
  async getCircleKey(circleId: string, epoch: number) {
    const name = ckName(this.userId, circleId, epoch)
    if (!this.kv) return this.mem.get(name)?.slice() ?? null
    const v = (await this.kv.get(name)) as Uint8Array | undefined
    if (!v) return null
    try {
      return xchacha20poly1305(this.key, v.slice(0, 24), utf8(name)).decrypt(v.slice(24))
    } catch {
      return null
    }
  }
  async heldEpochs(circleId: string) {
    if (!this.kv) return epochsFrom([...this.mem.keys()].filter((k) => k.startsWith(`ck:${this.userId}:${circleId}:`)))
    return epochsFrom(await this.kv.keys(`ck:${this.userId}:${circleId}:`))
  }
}

function epochsFrom(names: string[]): number[] {
  return names
    .map((n) => Number(n.slice(n.lastIndexOf(':') + 1)))
    .filter((n) => Number.isInteger(n) && n > 0)
    .sort((a, b) => a - b)
}

// ------------------------------------------------------------- identity records

export interface IdentityMeta {
  mode: CustodyMode
  userId: string
  deviceId: string
  name: string
  edPub: string // b64
  xPub: string // b64
  registered: boolean
  createdAt: number
  /** The approving phone, pinned from the approval signature (the root of trust for our own account). */
  approver?: { deviceId: string; edPub: string }
}

interface StoredDevice extends IdentityMeta {
  mode: 'device'
  edPriv: CryptoKey
  xPriv: CryptoKey
  aes: CryptoKey
}

interface StoredPassphrase extends IdentityMeta {
  mode: 'passphrase'
  salt: Uint8Array
  nonce: Uint8Array
  sealed: Uint8Array
  m: number
  t: number
}

export const ARGON_M_KIB = 64 * 1024
export const ARGON_T = 3

const idKey = (userId: string) => `identity:${userId}`

export interface Unlocked {
  meta: IdentityMeta
  ops: KeyOps
  vault: Vault
}

async function passKeys(pass: string, salt: Uint8Array, m: number, t: number) {
  const root = await argon2idAsync(utf8(pass.normalize('NFKC')), salt, { t, m, p: 1, dkLen: 32 })
  return {
    seedKey: hkdfSha256(root, undefined, utf8('OFE2EE-VIEWER-SEED'), 32),
    vaultKey: hkdfSha256(root, undefined, utf8('OFE2EE-VIEWER-CIRCLEKEYS'), 32),
  }
}

export interface CreateOpts {
  kv: KV
  mode: CustodyMode
  userId: string
  deviceId: string
  name: string
  passphrase?: string
  /** Tests may lower the Argon2 cost. */
  argon?: { m: number; t: number }
}

/** Creates a new viewer identity in the chosen custody mode and (unless session) stores it. */
export async function createIdentity(o: CreateOpts): Promise<Unlocked> {
  if (o.mode === 'account') throw new E2eeError('account-bound keys are made by accountAccess.ts')
  const base = { userId: o.userId, deviceId: o.deviceId, name: o.name, registered: false, createdAt: Date.now() }
  if (o.mode === 'device') {
    const ed = (await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair
    const x = (await crypto.subtle.generateKey({ name: 'X25519' }, false, ['deriveBits'])) as CryptoKeyPair
    const aes = (await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt'])) as CryptoKey
    const edPub = new Uint8Array(await crypto.subtle.exportKey('raw', ed.publicKey))
    const xPub = new Uint8Array(await crypto.subtle.exportKey('raw', x.publicKey))
    const meta: StoredDevice = { ...base, mode: 'device', edPub: b64(edPub), xPub: b64(xPub), edPriv: ed.privateKey, xPriv: x.privateKey, aes }
    await o.kv.put(idKey(o.userId), meta)
    return { meta, ops: new WebCryptoOps(ed.privateKey, x.privateKey, edPub, xPub), vault: new AesVault(o.kv, o.userId, aes) }
  }
  const seed = randomBytes(32)
  const { edSeed, xSecret } = deriveIdentity(seed)
  const ops = new MemoryOps(o.mode, edSeed, xSecret)
  const meta: IdentityMeta = { ...base, mode: o.mode, edPub: b64(ops.edPub), xPub: b64(ops.xPub) }
  if (o.mode === 'session') return { meta, ops, vault: new XChaChaVault('session', null, o.userId, randomBytes(32)) }
  if (!o.passphrase || o.passphrase.length < 8) throw new E2eeError('choose a passphrase of at least 8 characters')
  const m = o.argon?.m ?? ARGON_M_KIB
  const t = o.argon?.t ?? ARGON_T
  const salt = randomBytes(16)
  const nonce = randomBytes(24)
  const { seedKey, vaultKey } = await passKeys(o.passphrase, salt, m, t)
  const stored: StoredPassphrase = {
    ...meta,
    mode: 'passphrase',
    salt,
    nonce,
    m,
    t,
    sealed: xchacha20poly1305(seedKey, nonce, utf8(idKey(o.userId))).encrypt(seed),
  }
  await o.kv.put(idKey(o.userId), stored)
  return { meta, ops, vault: new XChaChaVault('passphrase', o.kv, o.userId, vaultKey) }
}

export async function loadMeta(kv: KV, userId: string): Promise<IdentityMeta | null> {
  const v = (await kv.get(idKey(userId))) as IdentityMeta | undefined
  if (!v) return null
  return { mode: v.mode, userId: v.userId, deviceId: v.deviceId, name: v.name, edPub: v.edPub, xPub: v.xPub, registered: v.registered, createdAt: v.createdAt, approver: v.approver }
}

export async function markRegistered(kv: KV, userId: string, approver: { deviceId: string; edPub: string }): Promise<void> {
  const v = (await kv.get(idKey(userId))) as IdentityMeta | undefined
  if (v) await kv.put(idKey(userId), { ...v, registered: true, approver })
}

/** Opens a stored identity. Passphrase mode needs the passphrase (wrong one throws). */
export async function unlockIdentity(kv: KV, userId: string, passphrase?: string): Promise<Unlocked | null> {
  const v = (await kv.get(idKey(userId))) as (StoredDevice | StoredPassphrase) | undefined
  if (!v) return null
  const meta = (await loadMeta(kv, userId))!
  if (v.mode === 'device') {
    return {
      meta,
      ops: new WebCryptoOps(v.edPriv, v.xPriv, unb64(v.edPub), unb64(v.xPub)),
      vault: new AesVault(kv, userId, v.aes),
    }
  }
  if (v.mode !== 'passphrase') return null
  if (!passphrase) throw new E2eeError('passphrase required')
  const { seedKey, vaultKey } = await passKeys(passphrase, v.salt, v.m, v.t)
  let seed: Uint8Array
  try {
    seed = xchacha20poly1305(seedKey, v.nonce, utf8(idKey(userId))).decrypt(v.sealed)
  } catch {
    throw new E2eeError('wrong passphrase')
  }
  const { edSeed, xSecret } = deriveIdentity(seed)
  return { meta, ops: new MemoryOps('passphrase', edSeed, xSecret), vault: new XChaChaVault('passphrase', kv, userId, vaultKey) }
}

/** Forgets everything this browser holds for the account (the server-side key must be revoked separately). */
export async function wipeIdentity(kv: KV, userId: string): Promise<void> {
  await kv.del(idKey(userId))
  for (const k of await kv.keys(`ck:${userId}:`)) await kv.del(k)
  await kv.del(`pin:${userId}`)
}

export async function getPin(kv: KV, userId: string): Promise<{ seq: number; hash: string } | null> {
  return ((await kv.get(`pin:${userId}`)) as { seq: number; hash: string } | undefined) ?? null
}
export async function setPin(kv: KV, userId: string, head: { seq: number; hash: string }): Promise<void> {
  await kv.put(`pin:${userId}`, head)
}
